 public static void bind(Object owner,View root){if(root==null)return;root.post(()->{try{
  Bundle data=(Bundle)Review181.field(owner,"i0");if(data==null)return;attach(root,data.getString("videoId",""));
 }catch(Exception ignored){}});}
 static void attach(View root,String id){if(!id.matches("(?:sm|nm|so|ss)[0-9]+") )return;View existing=root.findViewWithTag("nicoid_nicoad");if(existing!=null){existing.setOnClickListener(v->open(root.getContext(),id));return;}
  View like=root.findViewWithTag("nicoid_like");if(like==null||!(like.getParent() instanceof LinearLayout))return;
  LinearLayout parent=(LinearLayout)like.getParent();int index=parent.indexOfChild(like);LinearLayout actions=parent;
  int height=PanelUi.dp(root.getContext(),40);
  LinearLayout.LayoutParams likeParams=new LinearLayout.LayoutParams(height,height);likeParams.gravity=Gravity.CENTER_VERTICAL;like.setLayoutParams(likeParams);if(like instanceof TextView){((TextView)like).setIncludeFontPadding(false);((TextView)like).setGravity(Gravity.CENTER);}
  if(parent.getOrientation()==LinearLayout.VERTICAL){ViewGroup.LayoutParams saved=like.getLayoutParams();parent.removeView(like);actions=new LinearLayout(root.getContext());actions.setGravity(Gravity.CENTER_VERTICAL);LinearLayout.LayoutParams actionParams=new LinearLayout.LayoutParams(-1,-2);actionParams.topMargin=PanelUi.dp(root.getContext(),12);parent.addView(actions,index,actionParams);actions.addView(like,saved);index=0;}
  Button ad=new AdIcon(root.getContext());ad.setTag("nicoid_nicoad");ad.setContentDescription(PanelUi.tr(root.getContext(),"ニコニ広告","Niconi Ads","Niconi 廣告"));ad.setOnClickListener(v->open(root.getContext(),id));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(height,height);lp.setMargins(PanelUi.dp(root.getContext(),4),0,0,0);actions.addView(ad,index+1,lp);
 }
 static void open(Context host,String id){if(!id.matches("(?:sm|nm|so|ss)[0-9]+"))return;VideoDetails.initializeCookies(host);Context c=PlaybackSession.dialogContext(host);Dialog dialog=new Dialog(c);dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout page=PanelUi.column(c);page.setPadding(0,0,0,0);ThemeChoice.background(page);
  LinearLayout bar=new LinearLayout(c);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(PanelUi.dp(c,8),0,0,0);bar.setBackgroundColor(UiDialogs.surface(c));TextView title=PanelUi.text(c,PanelUi.tr(c,"ニコニ広告","Niconi Ads","Niconi 廣告"),14);bar.addView(title,new LinearLayout.LayoutParams(0,-2,1));Button close=PanelUi.button(c,"×");close.setPadding(0,0,0,0);close.setMinHeight(0);close.setMinimumHeight(0);close.setContentDescription(UiStrings.translate("閉じる"));bar.addView(close,new LinearLayout.LayoutParams(PanelUi.dp(c,40),PanelUi.dp(c,40)));page.addView(bar,new LinearLayout.LayoutParams(-1,PanelUi.dp(c,40)));
  ProgressBar progress=new ProgressBar(c,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(100);progress.setProgressTintList(android.content.res.ColorStateList.valueOf(UiDialogs.accent(c)));page.addView(progress,new LinearLayout.LayoutParams(-1,PanelUi.dp(c,3)));
  WebView web=new WebView(c);web.setBackgroundColor(UiDialogs.surface(c));WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(true);settings.setAllowFileAccess(false);settings.setAllowContentAccess(false);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);if(Build.VERSION.SDK_INT>=26)settings.setSafeBrowsingEnabled(true);
  CookieManager cookies=CookieManager.getInstance();cookies.setAcceptCookie(true);String session="";for(String pair:VideoDetails.cookie().split(";")){String value=pair.trim();if(value.startsWith("user_session=")||value.startsWith("user_session_secure="))cookies.setCookie("https://nicoad.nicovideo.jp",value+"; Domain=.nicovideo.jp; Path=/; Secure; HttpOnly");if(value.startsWith("user_session="))session=value;}if(session.isEmpty()){for(String key:new String[]{"user_session","user_session_secure"})cookies.setCookie("https://nicoad.nicovideo.jp",key+"=; Domain=.nicovideo.jp; Path=/; Max-Age=0; Secure");}cookies.flush();
  web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView view,String url){Uri u=Uri.parse(url);String h=u.getHost();if("https".equals(u.getScheme())&&h!=null&&(h.equals("nicovideo.jp")||h.endsWith(".nicovideo.jp")))return false;try{if("https".equals(u.getScheme()))host.startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception ignored){}return true;}});
  web.setWebChromeClient(new WebChromeClient(){public void onProgressChanged(WebView view,int value){progress.setProgress(value);progress.setVisibility(value==100?View.GONE:View.VISIBLE);}});page.addView(web,new LinearLayout.LayoutParams(-1,0,1));dialog.setContentView(page);close.setOnClickListener(v->dialog.dismiss());dialog.setOnKeyListener((d,key,e)->{if(key!=KeyEvent.KEYCODE_BACK||e.getAction()!=KeyEvent.ACTION_UP)return false;if(web.canGoBack())web.goBack();else dialog.dismiss();return true;});dialog.setOnDismissListener(d->{web.stopLoading();web.loadUrl("about:blank");page.removeView(web);web.destroy();});dialog.show();if(dialog.getWindow()!=null){dialog.getWindow().setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(UiDialogs.surface(c)));dialog.getWindow().getDecorView().setPadding(0,0,0,0);dialog.getWindow().setLayout(-1,-1);}web.loadUrl("https://nicoad.nicovideo.jp/video/publish/"+id+"?frontend_id=6&frontend_version=0");
 }
 private static final class AdIcon extends Button {final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);AdIcon(Context c){super(c);setText("");setPadding(0,0,0,0);setMinimumWidth(0);setMinimumHeight(0);setMinWidth(0);setMinHeight(0);Ui110.circle(this);}protected void onDraw(Canvas c){float s=Math.min(getWidth(),getHeight())/32f;c.save();c.translate((getWidth()-32*s)/2,(getHeight()-32*s)/2);c.scale(s,s);c.translate(16,16);c.scale(.64f,.64f);c.translate(-16,-16);p.setColor(UiDialogs.accent(getContext()));p.setStyle(Paint.Style.FILL);Path cone=new Path();cone.moveTo(9,14);cone.lineTo(23,7);cone.lineTo(23,23);cone.lineTo(9,18);cone.close();c.drawPath(cone,p);c.drawRect(6,13,10,19,p);Path grip=new Path();grip.moveTo(11,18);grip.lineTo(16,20);grip.lineTo(13,27);grip.lineTo(9,25);grip.close();c.drawPath(grip,p);p.setStrokeWidth(1.8f);c.drawLine(26,10,29,7,p);c.drawLine(27,16,31,16,p);c.drawLine(26,22,29,25,p);c.restore();}}
